function f = HS22_f(x)
f = (x(1) - 2).^2 + (x(2) - 1).^2;
end

function g = HS22_g(x)
g = zeros(2, 1);
g(1) = 2*x(1) - 4;
g(2) = 2*x(2) - 2;
end

function c = HS22_c(x)
c = zeros(2, 1);
c(1) = -x(1) - x(2) + 2;
c(2) = -x(1).^2 + x(2);
end

function J = HS22_J(x)
